//! Vectors for the frame's sizing and plan functions, generated by
//! `scripts/cpp_vectors/frame_sizes_vectors.cpp` from `fixtures/config/policy.txt`:
//! `lin_sized`/`lin_size_of`/`lin_plan_first`/`lin_plan_shared`/`lin_plan_second`,
//! `link_sized`/`link_plan`, `wf_sized`/`wf_plan` and `req_plan`.
//!
//! The test rebuilds every case with the port and renders the same lines as the C++ tool, so every
//! field of every shape, code list, stage, refusal and plan round must match. The one deliberate
//! deviation is the `OneList` counter: the C++ headers keep it in a static; the port threads a
//! `last` through `tree_sizes` and `plan_iopp`. It numbers trees only, which no line prints.

use std::rc::Rc;

use fp_core::frame::derive::{derive, solve_group, Derived, FrameShape, TestSizes};
use fp_core::frame::lin_frame::{
    lin_lines, lin_plan_first, lin_plan_second, lin_plan_shared, lin_sized, LinSized,
};
use fp_core::frame::link_frame::{link_lines, link_plan, link_sized, LinkSized};
use fp_core::frame::parameters::{read_parameters, Parameters, StageChoice};
use fp_core::frame::wf_frame::{wf_lines, wf_plan, wf_sized, WfLines, WfShape, WfSized};
use fp_core::frame::wf_units::{wf_shape_of_layout, WfUnit};
use fp_core::iop::context::{tree_sizes, OracleNotice};
use fp_core::iop::iopp::{iopp_stages, IoppStage};
use fp_core::iop::req::{req_plan, ReqLink, ReqMessage, ReqShape, ReqSizes};
use fp_core::iop::relation::{Codes, OracleShape};
use fp_core::numbers::blocks::{solve_stages, GroupSize, TableSize};
use fp_core::numbers::codes::{CodeSize, Radius};
use fp_core::numbers::plan::{MessageKind, Plan, PlanMessage, PlanRound, Planned, Priced, TableTest};
use fp_core::numbers::real::{Big, Real};
use fp_core::numbers::round_names::R_REPLY;
use fp_core::numbers::setting::{Scope, Setting};

use fp_core::iop::foldeq::IndexShape;

const VECTORS: &str = include_str!("../../fixtures/frame_sizes_vectors.txt");

// ---------------------------------------------------------------------------------------------------------------------
// The C++ tool's line format

fn hex(s: &str) -> String {
    s.as_bytes().iter().map(|b| format!("{b:02x}")).collect()
}

fn hex_or_dash(s: &str) -> String {
    if s.is_empty() {
        String::from("-")
    } else {
        hex(s)
    }
}

fn group_str(g: &GroupSize) -> String {
    format!(
        "name={} main={},{},{},{} mask={},{},{},{} k={} h={} slots={} rule={} m={}",
        hex(&g.name),
        g.main.log_n,
        g.main.ell,
        g.main.r,
        g.main.over_e as u8,
        g.mask.log_n,
        g.mask.ell,
        g.mask.r,
        g.mask.over_e as u8,
        g.k,
        g.h,
        g.slots,
        g.rule as u8,
        g.m
    )
}

fn shape_str(o: &OracleShape) -> String {
    format!(
        "name={} code={} main_rows={} main_deg={} mask_rows={} mask_code={} answers={}",
        hex(&o.name),
        o.code,
        o.main_rows,
        o.main_deg,
        o.mask_rows,
        o.mask_code,
        o.answers
    )
}

fn index_str(s: &IndexShape) -> String {
    format!(
        "log_n={} ell={} r={} v={} answers={} salt={} radius={} later={} m_once={} m_later={}",
        s.code.log_n,
        s.code.ell,
        s.code.r,
        s.v,
        s.answers,
        s.salt_bytes,
        s.distances.radius,
        s.distances.later_radius,
        s.distances.m_once,
        s.distances.m_later
    )
}

fn table_str(t: &TableSize) -> String {
    format!(
        "log_n={} ell={} r={} v={} answers={} radius={} later={} m_once={} m_later={}",
        t.code.log_n,
        t.code.ell,
        t.code.r,
        t.v,
        t.answers,
        t.distances.radius,
        t.distances.later_radius,
        t.distances.m_once,
        t.distances.m_later
    )
}

fn push_test(out: &mut String, name: &str, test: &str, x: &TestSizes) {
    out.push_str(&format!(
        "LTEST name={} test={} t={} group={} stages={}\n",
        name,
        test,
        x.t,
        group_str(&x.group),
        x.stages.len()
    ));
    for (i, s) in x.stages.iter().enumerate() {
        out.push_str(&format!(
            "LSTAGE name={} test={} i={} t={} r_ood={} group={}\n",
            name,
            test,
            i,
            s.t,
            s.r_ood,
            group_str(&s.g)
        ));
    }
}

fn push_codes(out: &mut String, name: &str, codes: &Codes) {
    out.push_str(&format!(
        "LCODES name={} base={} mask={}\n",
        name,
        codes.base.len(),
        codes.mask.len()
    ));
    for (i, c) in codes.base.iter().enumerate() {
        out.push_str(&format!(
            "LCODE name={} kind=base i={} log_n={} ell={} r={}\n",
            name, i, c.log_n, c.ell, c.r
        ));
    }
    for (i, c) in codes.mask.iter().enumerate() {
        out.push_str(&format!(
            "LCODE name={} kind=mask i={} log_n={} ell={} r={}\n",
            name, i, c.log_n, c.ell, c.r
        ));
    }
}

fn push_lin(out: &mut String, name: &str, x: &LinSized, codes: &Codes) {
    let s = &x.s;
    out.push_str(&format!(
        "LIN name={} refused={} k_lo={} matrix_rows={} omega_rh={} w_rh={} masks_ahead={} ride={} shared_mask={} own_mask={} batches={} shared_split={} own_split={} columns={} fold_rh={} omega_lc={} split_lc={} w_lc={} own_lc={}\n",
        name,
        hex_or_dash(&x.refused),
        s.k_lo,
        s.matrix_rows,
        s.omega_rows_high as u8,
        s.w_rows_high as u8,
        s.masks_ahead as u8,
        s.choice.masks_ride as u8,
        s.shared_mask_code,
        s.own_mask_code,
        x.batches,
        s.shared_split_needed() as u8,
        s.own_split_needed() as u8,
        s.fold.columns,
        s.fold.rows_high as u8,
        s.omega_leaf_class,
        s.shared_split_leaf_class,
        s.w_leaf_class,
        s.own_split_leaf_class
    ));
    out.push_str(&format!("LINDEX name={} {}\n", name, index_str(&s.fold.index)));
    out.push_str(&format!(
        "LSHAPE name={} at=fold.u {} leaf={}\n",
        name,
        shape_str(&s.fold.u),
        s.fold.leaf_class
    ));
    out.push_str(&format!("LSHAPE name={} at=omega {}\n", name, shape_str(&s.omega)));
    out.push_str(&format!("LSHAPE name={} at=w {}\n", name, shape_str(&s.w)));
    out.push_str(&format!(
        "LSHAPE name={} at=shared_split {}\n",
        name,
        shape_str(&s.shared_split)
    ));
    out.push_str(&format!("LSHAPE name={} at=own_split {}\n", name, shape_str(&s.own_split)));
    out.push_str(&format!(
        "LINPUT name={} {} leaf={}\n",
        name,
        shape_str(&x.input.shape),
        x.input.leaf_class
    ));
    push_test(out, name, "folded", &x.folded);
    push_test(out, name, "omega", &x.omega);
    push_test(out, name, "own", &x.own);
    for (label, stages) in [
        ("u", &s.test_u),
        ("omega", &s.test_omega),
        ("own", &s.test_own),
        ("own_omega", &s.test_own_omega),
    ] {
        out.push_str(&format!("LSTAGES name={} test={} n={}\n", name, label, stages.len()));
        for (i, st) in stages.iter().enumerate() {
            out.push_str(&format!(
                "LIOPP name={} test={} i={} code={} mask_code={} k={} h={}\n",
                name, label, i, st.code, st.mask_code, st.k, st.h
            ));
        }
    }
    out.push_str(&format!("LTABLE name={} {}\n", name, table_str(&x.table)));
    push_codes(out, name, codes);
}

fn push_link(out: &mut String, name: &str, x: &LinkSized, codes: &Codes) {
    let s = &x.s;
    out.push_str(&format!(
        "LINK name={} refused={} columns_first={} columns_further={} code={} mask_code={} rows={} rows_high={} leaf_class={} masks_ahead={} ride={} later={}\n",
        name,
        hex_or_dash(&x.refused),
        s.columns_first,
        s.columns_further,
        s.code,
        s.mask_code,
        s.rows,
        s.rows_high as u8,
        s.leaf_class,
        s.masks_ahead as u8,
        s.choice.masks_ride as u8,
        s.later.len()
    ));
    out.push_str(&format!("LINDEX name={} {}\n", name, index_str(&s.table)));
    for (i, st) in s.later.iter().enumerate() {
        out.push_str(&format!(
            "LLATER name={} i={} code={} mask_code={} k={} h={}\n",
            name, i, st.code, st.mask_code, st.k, st.h
        ));
    }
    push_test(out, name, "linked", &x.linked);
    out.push_str(&format!("LTABLE name={} {}\n", name, table_str(&x.table)));
    push_codes(out, name, codes);
}

fn push_wf(out: &mut String, name: &str, z: &WfSized, codes: &Codes) {
    let x = &z.x;
    out.push_str(&format!(
        "WF name={} refused={} k_col={} rows={} pending={} message_id={} ride={} own_masks={} rows_batched={} index_mask_entries={}\n",
        name,
        hex_or_dash(&z.refused),
        z.matrix.k_col,
        z.matrix.rows,
        z.pending,
        x.message_id,
        x.choice.masks_ride as u8,
        fp_core::iop::wf::wf_own_masks(x, &z.matrix),
        fp_core::iop::wf::wf_rows_batched(x, &z.matrix),
        fp_core::iop::wf::wf_index_mask_entries(x, &z.matrix)
    ));
    for (i, l) in x.lookups.iter().enumerate() {
        let weights: Vec<String> = l.digit_weight.iter().map(|w| w.0.to_string()).collect();
        let bounds: Vec<String> = l.first_bound.iter().map(|b| b.to_string()).collect();
        let weights = if weights.is_empty() { String::from("-") } else { weights.join(",") };
        let bounds = if bounds.is_empty() { String::from("-") } else { bounds.join(",") };
        out.push_str(&format!(
            "WLOOKUP name={} i={} name_hex={} d={} mu={} live={} weights={} offset={} pad={} first_bound={} parts={}\n",
            name,
            i,
            hex(&l.name),
            l.d,
            l.mu,
            l.live,
            weights,
            l.offset.0,
            l.padding_key.0,
            bounds,
            l.parts.len()
        ));
        for (j, p) in l.parts.iter().enumerate() {
            out.push_str(&format!(
                "WPART name={} i={} j={} log_places={} runs={}\n",
                name,
                i,
                j,
                p.log_places,
                p.runs.len()
            ));
            for (k, r) in p.runs.iter().enumerate() {
                out.push_str(&format!(
                    "WRUN name={} i={} j={} k={} first_place={} first_row={} places={} stride={}\n",
                    name, i, j, k, r.first_place, r.first_row, r.places, r.stride
                ));
            }
        }
    }
    out.push_str(&format!(
        "WSHAPE name={} {} leaf={}\n",
        name,
        shape_str(&x.message.shape),
        x.message.leaf_class
    ));
    out.push_str(&format!("WSTAGES name={} n={}\n", name, x.stages.len()));
    for (i, st) in x.stages.iter().enumerate() {
        out.push_str(&format!(
            "WIOPP name={} i={} code={} mask_code={} k={} h={}\n",
            name, i, st.code, st.mask_code, st.k, st.h
        ));
    }
    push_test(out, name, "test", &z.test);
    push_codes(out, name, codes);
}

fn big_hex(b: &Big) -> String {
    if b.is_zero() {
        return String::from("0");
    }
    b.w.iter().map(|w| format!("{:08x}", w)).collect::<Vec<_>>().join(",")
}

fn real_str(r: &Real) -> String {
    format!("{}@{}", big_hex(&r.m), r.e)
}

fn priced_int(p: Priced) -> u32 {
    match p {
        Priced::Nothing => 0,
        Priced::SettingAlone => 1,
        Priced::TheRoundItself => 2,
        Priced::AsSaid => 3,
        Priced::OnTheCallersWord => 4,
    }
}

fn table_test_int(t: TableTest) -> u32 {
    match t {
        TableTest::Later => 0,
        TableTest::OneTime => 1,
        TableTest::Link => 2,
    }
}

fn message_kind_int(k: MessageKind) -> u32 {
    match k {
        MessageKind::Scalars => 0,
        MessageKind::Answers => 1,
        MessageKind::Root => 2,
        MessageKind::Nonce => 3,
        MessageKind::Columns => 4,
        MessageKind::Salts => 5,
        MessageKind::Paths => 6,
        MessageKind::Head => 7,
    }
}

fn round_line(i: usize, r: &PlanRound) -> String {
    format!(
        "ROUND\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\n",
        i,
        hex(&r.name),
        hex(&r.where_),
        r.kind as u32,
        r.why as usize,
        r.scope as usize,
        real_str(&r.error),
        r.rests as u32,
        r.work_bits,
        r.count,
        r.part,
        r.message_bytes,
        r.roots,
        r.answers,
        r.draw_e,
        r.draw_nonzero,
        r.draw_positions,
        r.log_n,
        r.draw_trits,
        r.rows,
        r.first_list,
        r.combinations,
        r.sharing,
        priced_int(r.priced),
        r.group.said as u8,
        r.group.main.log_n,
        r.group.main.ell,
        r.group.main.r,
        r.group.mask.log_n,
        r.group.mask.ell,
        r.group.mask.r,
        r.group.k,
        r.group.h,
        r.group.slots,
        r.group.rule,
        r.group.m,
        r.table.said as u8,
        r.table.code.log_n,
        r.table.code.ell,
        r.table.code.r,
        r.table.v,
        r.table.answers,
        r.table.distances.radius,
        r.table.distances.later_radius,
        r.table.distances.m_once,
        r.table.distances.m_later,
        table_test_int(r.table.test)
    )
}

fn msg_line(i: usize, m: &PlanMessage) -> String {
    format!(
        "MSG\t{}\t{}\t{}\t{}\t{}\t{:x}\t{}\t{}\t{}\t{}\n",
        i,
        hex(&m.name),
        hex(&m.where_),
        message_kind_int(m.kind),
        m.bytes,
        m.expected.to_bits(),
        m.count,
        m.part,
        m.in_chain as u8,
        m.hash_calls
    )
}

fn push_plan(out: &mut String, name: &str, p: &Plan) {
    let q: Rc<Planned> = p.finish();
    out.push_str(&format!("PLAN name={}\n", name));
    out.push_str(&format!("VERDICT {} {}\n", q.cause() as u32, hex_or_dash(q.why_not())));
    for (i, part) in q.parts.iter().enumerate() {
        out.push_str(&format!("PART {} {}\n", i, hex(part)));
    }
    for (i, r) in q.rounds.iter().enumerate() {
        out.push_str(&round_line(i, r));
    }
    for (i, m) in q.messages.iter().enumerate() {
        out.push_str(&msg_line(i, m));
    }
}

// ---------------------------------------------------------------------------------------------------------------------
// The cases

fn table_tree_of(s: &Setting, p: &Parameters) -> fp_core::numbers::blocks::TreeSize {
    fp_core::numbers::blocks::TreeSize {
        name: String::from("table"),
        log_n: p.table_log_n,
        leaf_bytes: (s.f_bytes as u64) << p.table_rows_log,
        ..Default::default()
    }
}

fn frame_shape() -> FrameShape {
    FrameShape { index_rows: 1u64 << 15, ..FrameShape::default() }
}

fn dump_lin_cases(out: &mut String, p: &Parameters, set: &Setting, d: &Derived) {
    let shape = frame_shape();
    {
        let mut codes = Codes::default();
        let x = lin_sized(set, &lin_lines(p, &shape, false), &d.table, &mut codes);
        push_lin(out, "lin_normal", &x, &codes);
        if x.refused.is_empty() {
            let tree = table_tree_of(set, p);
            let mut q = Plan::new(set.clone());
            q.begin_scope(Scope::Shared);
            let mut last = 0u64;
            lin_plan_shared(&mut q, &codes, &x, &tree, &mut last);
            fp_core::numbers::blocks::plan_seal(&mut q, "seal");
            push_plan(out, "lin_normal_shared", &q);

            let mut r = Plan::new(set.clone());
            r.begin_scope(Scope::Request);
            fp_core::numbers::blocks::plan_chain_start(&mut r, "second chain", true);
            let mut last = 0u64;
            let input_trees = tree_sizes(&codes, &[x.input.clone()], &mut last);
            lin_plan_second(&mut r, &codes, &x, &input_trees, &mut last);
            fp_core::numbers::blocks::plan_seal(&mut r, "seal");
            push_plan(out, "lin_normal_second", &r);

            let mut f = Plan::new(set.clone());
            f.begin_scope(Scope::Request);
            lin_plan_first(&mut f, &codes, &x);
            fp_core::numbers::blocks::plan_seal(&mut f, "seal");
            push_plan(out, "lin_normal_first", &f);
        }
    }
    {
        let mut codes = Codes::default();
        let x = lin_sized(set, &lin_lines(p, &shape, true), &d.table, &mut codes);
        push_lin(out, "lin_once", &x, &codes);
        if x.refused.is_empty() {
            let tree = table_tree_of(set, p);
            let mut q = Plan::new(set.clone());
            q.begin_scope(Scope::Once);
            let mut last = 0u64;
            lin_plan_shared(&mut q, &codes, &x, &tree, &mut last);
            fp_core::numbers::blocks::plan_seal(&mut q, "seal");
            push_plan(out, "lin_once_shared", &q);
        }
    }
    {
        // No split: Omega is the folded row's code and a request's group is Omega's.
        let mut lines = lin_lines(p, &shape, false);
        lines.omega = lines.folded.clone();
        lines.own = lines.folded.clone();
        lines.folded.stages = p.omega.stages.clone();
        lines.own.stages = p.omega.stages.clone();
        lines.own.mask_log_ell = 10;
        let mut codes = Codes::default();
        let x = lin_sized(set, &lines, &d.table, &mut codes);
        push_lin(out, "lin_no_split", &x, &codes);
        if x.refused.is_empty() {
            let tree = table_tree_of(set, p);
            let mut q = Plan::new(set.clone());
            q.begin_scope(Scope::Shared);
            let mut last = 0u64;
            lin_plan_shared(&mut q, &codes, &x, &tree, &mut last);
            fp_core::numbers::blocks::plan_seal(&mut q, "seal");
            push_plan(out, "lin_no_split_shared", &q);
        }
    }
    {
        // A request's mask message with three rows.
        let mut lines = lin_lines(p, &shape, false);
        lines.input_mask_rows = 3;
        let mut codes = Codes::default();
        let x = lin_sized(set, &lines, &d.table, &mut codes);
        push_lin(out, "lin_input_three", &x, &codes);
    }
    {
        // Refusals.
        let mut lines = lin_lines(p, &shape, false);
        lines.own.log_n = p.omega.log_n + 1;
        let mut codes = Codes::default();
        let x = lin_sized(set, &lines, &d.table, &mut codes);
        push_lin(out, "lin_refuse_own", &x, &codes);
    }
    {
        let mut lines = lin_lines(p, &shape, false);
        lines.folded.mask_log_n = p.omega.mask_log_n + 1;
        let mut codes = Codes::default();
        let x = lin_sized(set, &lines, &d.table, &mut codes);
        push_lin(out, "lin_refuse_split_mask", &x, &codes);
    }
    {
        let mut bad = d.table.clone();
        bad.distances.radius = bad.code.n();
        bad.distances.later_radius = bad.code.n();
        bad.distances.m_once = 0;
        bad.distances.m_later = 0;
        let mut codes = Codes::default();
        let x = lin_sized(set, &lin_lines(p, &shape, false), &bad, &mut codes);
        push_lin(out, "lin_refuse_table", &x, &codes);
    }
}

fn dump_link_cases(out: &mut String, p: &Parameters, set: &Setting, d: &Derived) {
    {
        let mut codes = Codes::default();
        let x = link_sized(set, &link_lines(p), &d.table, &mut codes);
        push_link(out, "link_normal", &x, &codes);
        if x.refused.is_empty() {
            let mut q = Plan::new(set.clone());
            q.begin_scope(Scope::Once);
            let mut last = 0u64;
            link_plan(&mut q, &codes, &x, &table_tree_of(set, p), &mut last);
            fp_core::numbers::blocks::plan_seal(&mut q, "seal");
            push_plan(out, "link_normal_plan", &q);
        }
    }
    {
        // The table's numbers belong to another table.
        let mut lines = link_lines(p);
        lines.table_log_n += 1;
        let mut codes = Codes::default();
        let x = link_sized(set, &lines, &d.table, &mut codes);
        push_link(out, "link_refuse_table", &x, &codes);
    }
    {
        // Distances that are not admitted.
        let mut bad = d.table.clone();
        bad.distances.radius = bad.code.n();
        bad.distances.later_radius = bad.code.n();
        bad.distances.m_once = 0;
        bad.distances.m_later = 0;
        let mut codes = Codes::default();
        let x = link_sized(set, &link_lines(p), &bad, &mut codes);
        push_link(out, "link_refuse_distance", &x, &codes);
    }
}

fn wf_shape(p: &Parameters) -> WfShape {
    wf_shape_of_layout(
        p.block_log,
        65536,
        &[
            WfUnit { first_row: 0, rows: 4096, digits: 2 },
            WfUnit { first_row: 4096, rows: 61440, digits: 4 },
        ],
    )
}

fn dump_wf_cases(out: &mut String, p: &Parameters, set: &Setting) {
    let shape = wf_shape(p);
    {
        let mut codes = Codes::default();
        let lines: WfLines = wf_lines(&shape, &p.once_ranges, p.ranges_part);
        let z = wf_sized(set, &lines, &mut codes);
        push_wf(out, "wf_normal", &z, &codes);
        if z.refused.is_empty() {
            let mut q = Plan::new(set.clone());
            q.begin_scope(Scope::Once);
            let mut last = 0u64;
            wf_plan(&mut q, &codes, &z, &mut last);
            fp_core::numbers::blocks::plan_seal(&mut q, "seal");
            push_plan(out, "wf_normal_plan", &q);
        }
    }
    {
        // More parts than the limit allows.
        let mut codes = Codes::default();
        let lines = wf_lines(&shape, &p.once_ranges, 6);
        let z = wf_sized(set, &lines, &mut codes);
        push_wf(out, "wf_refuse_parts", &z, &codes);
    }
    {
        // A part would read more rows than the matrix has.
        let mut codes = Codes::default();
        let lines = wf_lines(&shape, &p.once_ranges, 17);
        let z = wf_sized(set, &lines, &mut codes);
        push_wf(out, "wf_refuse_part_rows", &z, &codes);
    }
    {
        // wf_lines rejects lookups that already have planes.
        let mut bad = shape.clone();
        bad.lookups[0].lookup.mu = 1;
        let mut codes = Codes::default();
        let lines = wf_lines(&bad, &p.once_ranges, p.ranges_part);
        let z = wf_sized(set, &lines, &mut codes);
        push_wf(out, "wf_refuse_planes", &z, &codes);
    }
    {
        // No look-up.
        let empty = WfShape { k_col: p.block_log, matrix_rows: 65536, lookups: Vec::new() };
        let mut codes = Codes::default();
        let lines = wf_lines(&empty, &p.once_ranges, p.ranges_part);
        let z = wf_sized(set, &lines, &mut codes);
        push_wf(out, "wf_refuse_empty", &z, &codes);
    }
}

fn dump_req_plan_case(out: &mut String) {
    let mut set = Setting::goldilocks();
    set.target = 32;
    set.samples = 1;

    let mut codes = Codes::default();
    let link_group = GroupSize {
        name: String::from("link"),
        main: CodeSize {
            name: String::from("link"),
            log_n: 8,
            ell: 64,
            r: 2,
            over_e: false,
        },
        mask: CodeSize {
            name: String::from("link mask"),
            log_n: 8,
            ell: 64,
            r: 2,
            over_e: true,
        },
        k: 1,
        h: 1,
        slots: 1,
        rule: Radius::Johnson,
        m: 0,
    };

    let mut sized = TestSizes { group: link_group.clone(), ..TestSizes::default() };
    let mut why = String::new();
    {
        let load = fp_core::numbers::blocks::GroupLoad {
            cube_bits: fp_core::numbers::blocks::stage_cube_bits(&link_group),
            messages: 1,
            batched_rows: 4,
        };
        assert!(solve_group(&set, Scope::Request, &load, |t| t, &mut sized, &mut why), "{}", why);
    }
    {
        let mut scratch = Plan::new(set.clone());
        sized.stages = solve_stages(
            &mut scratch,
            &sized.group,
            sized.t,
            &[StageChoice { k: 0, h: 0, log_n: 12, mask_log_n: 12 }],
        );
    }
    let last_stages: Vec<IoppStage> = iopp_stages(&sized.stages, &mut codes);

    let mut s = ReqShape::default();
    s.code = 0;
    s.mask_code = 0;
    s.answers = 1;
    s.choice.masks_ride = true;
    s.last = last_stages;
    let mut a = OracleShape {
        name: String::from("a"),
        code: 0,
        main_rows: 1,
        main_deg: 3,
        ..OracleShape::default()
    };
    a.answers = 1;
    let mut b = OracleShape {
        name: String::from("b"),
        code: 0,
        main_rows: 0,
        mask_rows: 1,
        mask_code: 0,
        ..OracleShape::default()
    };
    b.answers = 1;
    s.link = vec![
        ReqLink {
            name: String::from("first"),
            messages: vec![ReqMessage { shape: a, leaf_class: 0, moment: 0, life: 1 }],
            plain: 0,
        },
        ReqLink {
            name: String::from("second"),
            messages: vec![
                ReqMessage { shape: b.clone(), leaf_class: 1, moment: 0, life: 0 },
                ReqMessage { shape: b, leaf_class: 1, moment: 1, life: 0 },
            ],
            plain: 0,
        },
    ];

    let z = ReqSizes { group: sized.group.clone(), last: sized.stages.clone(), rows: vec![3, 4], at_start: GroupSize::default() };

    let mut p = Plan::new(set.clone());
    let sub = |q: &mut Plan, _l: usize, _m: u32, _last: &mut u64| {
        q.begin_scope(Scope::Shared);
        fp_core::numbers::blocks::plan_none(q, R_REPLY, "sub");
    };
    let mut last = 0u64;
    req_plan(&mut p, &codes, &s, &z, &sub, &mut last);
    fp_core::numbers::blocks::plan_seal(&mut p, "seal");
    push_plan(out, "req_plan", &p);

    // What rides at the start, and plain scalars: the riders are priced with z.at_start's list size.
    let mut t = s.clone();
    let masks = OracleShape {
        name: String::from("masks"),
        main_rows: 0,
        main_deg: 1,
        mask_rows: 1,
        mask_code: 0,
        answers: 1,
        ..OracleShape::default()
    };
    t.at_start.push(OracleNotice { shape: masks, leaf_class: 2 });
    t.link[0].plain = 2;
    let zr = ReqSizes {
        at_start: GroupSize { name: String::from("at start"), ..sized.group.clone() },
        ..z.clone()
    };
    let mut q = Plan::new(set.clone());
    let mut last = 0u64;
    req_plan(&mut q, &codes, &t, &zr, &sub, &mut last);
    fp_core::numbers::blocks::plan_seal(&mut q, "seal");
    push_plan(out, "req_plan_riders", &q);
}

/// One line of the C++ tool's output against the Rust renderer's. MSG field 6 is the expected
/// size, an average over positions computed through libm: the C++ and Rust libraries may differ in
/// the last bits, as in the plan-emitter vectors.
fn same_line(got: &str, want: &str) -> bool {
    if got == want {
        return true;
    }
    let g: Vec<&str> = got.split('\t').collect();
    let w: Vec<&str> = want.split('\t').collect();
    if g.len() != w.len() || g.first() != Some(&"MSG") {
        return false;
    }
    for i in 0..g.len() {
        if i != 6 && g[i] != w[i] {
            return false;
        }
    }
    let x = f64::from_bits(u64::from_str_radix(g[6], 16).unwrap());
    let y = f64::from_bits(u64::from_str_radix(w[6], 16).unwrap());
    let tol = 1e-9 * x.abs().max(y.abs()).max(1.0);
    (x - y).abs() <= tol
}

#[test]
fn frame_sizes_match_the_cpp_reference() {
    let at = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../fixtures/config/policy.txt");
    let text = std::fs::read(at).unwrap();
    let mut p = Parameters::default();
    read_parameters(&text, &mut p).unwrap();
    let d = derive(&p, &FrameShape::default());
    let set = d.set.clone();

    let mut out = String::new();
    out.push_str(&format!(
        "DERIVED refused={} table={}\n",
        hex_or_dash(&d.refused),
        table_str(&d.table)
    ));
    dump_lin_cases(&mut out, &p, &set, &d);
    dump_link_cases(&mut out, &p, &set, &d);
    dump_wf_cases(&mut out, &p, &set);
    dump_req_plan_case(&mut out);

    let got: Vec<&str> = out.lines().collect();
    let want: Vec<&str> = VECTORS.lines().collect();
    assert_eq!(got.len(), want.len(), "the number of lines");
    for i in 0..got.len() {
        if !same_line(got[i], want[i]) {
            let a = got[i];
            let b = want[i];
            panic!(
                "line {} differs\n  rust: {}\n  cpp:  {}",
                i + 1,
                if a.len() > 400 { &a[..400] } else { a },
                if b.len() > 400 { &b[..400] } else { b }
            );
        }
    }
}
